class Solution {
public:
    int longestPalindrome(vector<string>& words) {
        int cnt[26][26] = {0};
        for (auto& w : words) {
            cnt[w[0] - 'a'][w[1] - 'a']++;
        }

        int ans = 0;
        int center = 0;

        // Self-palindrome words like "aa"
        for (int i = 0; i < 26; i++) {
            ans += (cnt[i][i] / 2) * 4;
            if (cnt[i][i] % 2 == 1) center = 2;
        }

        // Mirrored pairs: "ab" with "ba", only count i < j to avoid double counting
        for (int i = 0; i < 26; i++) {
            for (int j = i + 1; j < 26; j++) {
                int pairs = min(cnt[i][j], cnt[j][i]);
                ans += pairs * 4;
            }
        }

        return ans + center;
    }
};
